package railflag

// Experiment events: the shared vectors from packages/eval/vectors/events-vectors.json (generated by
// packages/eval/vectors/build.ts), replayed through OpenFeature, and the sender against the fake relay.

import (
	"encoding/json"
	"fmt"
	"log/slog"
	"math"
	"net/http"
	"net/http/httptest"
	"os"
	"reflect"
	"strconv"
	"strings"
	"sync"
	"testing"
	"time"

	of "github.com/open-feature/go-sdk/openfeature"
)

func loadEventVectors(t *testing.T) map[string]any {
	t.Helper()
	data, err := os.ReadFile("../eval/vectors/events-vectors.json")
	if err != nil {
		t.Skip("event vectors not found (they live in the Railflag monorepo):", err)
	}
	v, err := parseJSON(data)
	if err != nil {
		t.Fatal(err)
	}
	return v.(map[string]any)
}

// asRecord gives a record (or nil) the JSON shape of the vectors.
func asRecord(r any) any {
	b, _ := json.Marshal(r)
	v, _ := parseJSON(b)
	return v
}

// evalContext turns a vector context into an OpenFeature one; targetingKey becomes the targeting key. go-sdk
// drops an empty targeting key, so an empty one stays an attribute, which keeps it as the vectors have it.
func evalContext(m map[string]any) of.EvaluationContext {
	attrs := map[string]any{}
	key := ""
	for k, v := range m {
		if s, ok := v.(string); ok && k == of.TargetingKey && s != "" {
			key = s
			continue
		}
		attrs[k] = v
	}
	return of.NewEvaluationContext(key, attrs)
}

// trackDetails is what an app passes to Track. Without a value it is go-sdk's zero value, whose value is 0.
func trackDetails(d any) of.TrackingEventDetails {
	if m, _ := d.(map[string]any); m != nil {
		if v, ok := m["value"].(float64); ok {
			return of.NewTrackingEventDetails(v)
		}
	}
	return of.TrackingEventDetails{}
}

// evaluate calls the typed method that matches the flag's type, as an app would.
func evaluate(c *of.Client, flags map[string]any, flag string, ctx of.EvaluationContext) of.EvaluationDetails {
	if f, _ := flags[flag].(map[string]any); f != nil && f["type"] == "string" {
		d, _ := c.StringValueDetails(bg, flag, "", ctx)
		return d.EvaluationDetails
	}
	d, _ := c.BooleanValueDetails(bg, flag, false, ctx)
	return d.EvaluationDetails
}

func (r *fakeRelay) posts() []eventPost {
	r.mu.Lock()
	defer r.mu.Unlock()
	return append([]eventPost(nil), r.eventPosts...)
}

// sent returns the exposures and events posted so far, in order, without ts (checked to be epoch ms).
func (r *fakeRelay) sent(t *testing.T) (exposures, events []any) {
	t.Helper()
	exposures, events = []any{}, []any{}
	strip := func(items any) []any {
		var out []any
		for _, x := range items.([]any) {
			m := map[string]any{}
			for k, v := range x.(map[string]any) {
				m[k] = v
			}
			if ts, _ := m["ts"].(float64); ts < 1.7e12 || ts != math.Trunc(ts) {
				t.Fatalf("ts %v is not epoch milliseconds", m["ts"])
			}
			delete(m, "ts")
			out = append(out, m)
		}
		return out
	}
	for _, p := range r.posts() {
		exposures = append(exposures, strip(p.body["exposures"])...)
		events = append(events, strip(p.body["events"])...)
	}
	return exposures, events
}

func eventsProvider(t *testing.T, snap map[string]any, o Options) (*fakeRelay, *Provider, *of.Client) {
	t.Helper()
	relay := newFakeRelay(t)
	relay.publish(snap, false)
	o.SDKKey, o.BaseURL, o.DisableStream = testKey, relay.URL, true
	p := mustProvider(t, o)
	if err := of.SetProviderAndWait(p); err != nil {
		t.Fatal(err)
	}
	return relay, p, of.NewDefaultClient()
}

// experimentSnapshot is testSnapshot plus checkout-button, a 50/50 split, in a running experiment or not.
func experimentSnapshot(version int, running bool) map[string]any {
	snap := testSnapshot(version, true)
	snap["flags"].(map[string]any)["checkout-button"] = testFlag("checkout-button", []any{"control", "blue"}, map[string]any{
		"type": "string", "fallthrough": map[string]any{"rollout": map[string]any{"weights": []any{50_000, 50_000}}}})
	if running {
		snap["experiments"] = map[string]any{"flags": []any{"checkout-button"}, "events": []any{"purchase"}}
	}
	return snap
}

type logBuffer struct {
	mu sync.Mutex
	b  strings.Builder
}

func (l *logBuffer) Write(p []byte) (int, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.b.Write(p)
}

func (l *logBuffer) count(s string) int {
	l.mu.Lock()
	defer l.mu.Unlock()
	return strings.Count(l.b.String(), s)
}

func testSender(t *testing.T, baseURL string, logs *logBuffer) *eventSender {
	t.Helper()
	o := Options{SDKKey: testKey, BaseURL: baseURL}
	if logs != nil {
		o.Logger = slog.New(slog.NewTextHandler(logs, nil))
	}
	src, err := newConfigSource(o)
	if err != nil {
		t.Fatal(err)
	}
	return newEventSender(src, time.Hour) // not started: the test flushes
}

// ---- the shared vectors -----------------------------------------------------------------

func TestExposureVectors(t *testing.T) {
	v := loadEventVectors(t)
	snap := v["snapshot"].(map[string]any)
	sent := 0
	for _, raw := range v["exposures"].([]any) {
		c := raw.(map[string]any)
		flag, ctx, want := c["flag"].(string), c["context"].(map[string]any), c["result"].(map[string]any)
		r := Evaluate(snap, flag, ctx, "")
		if got := asJSON(r); got["reason"] != want["reason"] || got["variationIndex"] != want["variationIndex"] {
			t.Fatalf("%s with %v: got %v, want %v", flag, ctx, got, want)
		}
		if got := asRecord(exposureFor(experimentsOf(snap), flag, ctx, r)); !reflect.DeepEqual(got, c["expect"]) {
			t.Errorf("exposure for %s with %v:\n got  %v\n want %v", flag, ctx, got, c["expect"])
		}
		if c["expect"] != nil {
			sent++
		}
	}
	if sent < 50 {
		t.Fatalf("only %d vectors send an exposure", sent)
	}
}

func TestTrackVectors(t *testing.T) {
	v := loadEventVectors(t)
	x := experimentsOf(v["snapshot"].(map[string]any))
	for _, raw := range v["tracks"].([]any) {
		c := raw.(map[string]any)
		event, ctx := c["event"].(string), c["context"].(map[string]any)
		if got := asRecord(trackFor(x, event, ctx, trackDetails(c["details"]).Value())); !reflect.DeepEqual(got, c["expect"]) {
			t.Errorf("track %s with %v, details %v:\n got  %v\n want %v", event, ctx, c["details"], got, c["expect"])
		}
	}
	user := map[string]any{"targetingKey": "u"}
	for _, bad := range []float64{math.NaN(), math.Inf(1), math.Inf(-1)} {
		if r := trackFor(x, "purchase", user, bad); r == nil || r.Value != 0 {
			t.Errorf("value %v: %+v", bad, r)
		}
	}
	if trackFor(nil, "purchase", user, 1) != nil || exposureFor(nil, "exp-split", user, Evaluate(v["snapshot"].(map[string]any), "exp-split", user, "")) != nil {
		t.Error("recorded without experiments")
	}
}

// The same vectors through OpenFeature: contexts, typed evaluation, Track, de-duplication and sending.
func TestEventVectorsThroughTheProvider(t *testing.T) {
	v := loadEventVectors(t)
	snap := v["snapshot"].(map[string]any)
	flags := snap["flags"].(map[string]any)
	relay, provider, client := eventsProvider(t, snap, Options{})
	wantExposures, wantEvents, seen := []any{}, []any{}, map[string]bool{}
	for _, raw := range v["exposures"].([]any) {
		c := raw.(map[string]any)
		flag, want := c["flag"].(string), c["result"].(map[string]any)
		d := evaluate(client, flags, flag, evalContext(c["context"].(map[string]any)))
		if string(d.Reason) != want["reason"] || d.Variant != strconv.Itoa(int(want["variationIndex"].(float64))) {
			t.Fatalf("%s with %v: got %s %s, want %v", flag, c["context"], d.Reason, d.Variant, want)
		}
		if e := c["expect"]; e != nil && !seen[fmt.Sprint(e)] {
			seen[fmt.Sprint(e)] = true
			wantExposures = append(wantExposures, e)
		}
	}
	for _, raw := range v["tracks"].([]any) {
		c := raw.(map[string]any)
		client.Track(bg, c["event"].(string), evalContext(c["context"].(map[string]any)), trackDetails(c["details"]))
		if e := c["expect"]; e != nil {
			wantEvents = append(wantEvents, e)
		}
	}
	provider.FlushEvents()
	exposures, events := relay.sent(t)
	if !reflect.DeepEqual(exposures, wantExposures) {
		t.Errorf("exposures:\n got  %v\n want %v", exposures, wantExposures)
	}
	if !reflect.DeepEqual(events, wantEvents) {
		t.Errorf("events:\n got  %v\n want %v", events, wantEvents)
	}
}

func TestEventSequences(t *testing.T) {
	v := loadEventVectors(t)
	snap := v["snapshot"].(map[string]any)
	flags := snap["flags"].(map[string]any)
	for _, raw := range v["sequences"].([]any) {
		s := raw.(map[string]any)
		t.Run(s["name"].(string), func(t *testing.T) {
			relay, provider, client := eventsProvider(t, snap, Options{})
			for _, x := range s["steps"].([]any) {
				step := x.(map[string]any)
				ctx := evalContext(step["context"].(map[string]any))
				if flag, ok := step["evaluate"].(string); ok {
					evaluate(client, flags, flag, ctx)
				} else {
					client.Track(bg, step["track"].(string), ctx, trackDetails(step["details"]))
				}
			}
			provider.FlushEvents()
			exposures, events := relay.sent(t)
			want := s["expect"].(map[string]any)
			if !reflect.DeepEqual(exposures, want["exposures"]) {
				t.Errorf("exposures:\n got  %v\n want %v", exposures, want["exposures"])
			}
			if !reflect.DeepEqual(events, want["events"]) {
				t.Errorf("events:\n got  %v\n want %v", events, want["events"])
			}
		})
	}
}

// ---- the sender ---------------------------------------------------------------------------

func TestSendsExposuresAndEventsWithKeyAndSDK(t *testing.T) {
	relay, provider, c := eventsProvider(t, experimentSnapshot(1, true), Options{})
	before := float64(time.Now().UnixMilli())
	user := of.NewEvaluationContext("user-42", map[string]any{"plan": "pro"})
	got, _ := c.StringValue(bg, "checkout-button", "x", user)
	c.StringValue(bg, "checkout-button", "x", user) // the same exposure again: sent once
	c.BooleanValue(bg, "new-checkout", false, user) // not in the experiment
	c.Track(bg, "purchase", user, of.NewTrackingEventDetails(49.9))
	c.Track(bg, "pageview", user, of.NewTrackingEventDetails(1)) // not counted by the experiment
	c.Track(bg, "purchase", of.NewEvaluationContext("", nil), of.NewTrackingEventDetails(5))
	provider.FlushEvents()
	after := float64(time.Now().UnixMilli())

	posts := relay.posts()
	if len(posts) != 1 {
		t.Fatalf("%d posts", len(posts))
	}
	p := posts[0]
	if p.header.Get("Authorization") != testKey || p.header.Get("Content-Type") != "application/json" {
		t.Errorf("headers %v", p.header)
	}
	if p.body["sdk"] != "go/"+Version || Version != "0.3.0" {
		t.Errorf("sdk %v", p.body["sdk"])
	}
	if at, _ := p.body["sentAt"].(float64); at < before || at > after {
		t.Errorf("sentAt %v not in [%v, %v]", p.body["sentAt"], before, after)
	}
	for _, x := range append(p.body["exposures"].([]any), p.body["events"].([]any)...) {
		if ts := x.(map[string]any)["ts"].(float64); ts < before || ts > after {
			t.Errorf("ts %v not in [%v, %v]", ts, before, after)
		}
	}
	variation := map[string]float64{"control": 0, "blue": 1}[got]
	exposures, events := relay.sent(t)
	if want := []any{map[string]any{"flag": "checkout-button", "variation": variation, "key": "user-42"}}; !reflect.DeepEqual(exposures, want) {
		t.Errorf("exposures %v", exposures)
	}
	if want := []any{map[string]any{"event": "purchase", "key": "user-42", "value": 49.9}}; !reflect.DeepEqual(events, want) {
		t.Errorf("events %v", events)
	}
}

func TestSendsNothingWithoutARunningExperiment(t *testing.T) {
	relay, provider, c := eventsProvider(t, experimentSnapshot(1, false), Options{})
	use := func(user string) {
		ctx := of.NewEvaluationContext(user, nil)
		c.StringValue(bg, "checkout-button", "x", ctx)
		c.Track(bg, "purchase", ctx, of.NewTrackingEventDetails(1))
	}
	for i := 0; i < 20; i++ {
		use(fmt.Sprintf("user-%d", i))
	}
	provider.FlushEvents()
	if n := len(relay.posts()); n != 0 {
		t.Fatalf("%d posts without an experiment", n)
	}

	// The experiment starts: the next config has it.
	relay.publish(experimentSnapshot(2, true), false)
	if _, err := provider.Source().Fetch(bg); err != nil {
		t.Fatal(err)
	}
	use("user-1")
	provider.FlushEvents()
	if x, e := relay.sent(t); len(x) != 1 || len(e) != 1 {
		t.Fatalf("sent %v %v", x, e)
	}

	// And stops.
	relay.publish(experimentSnapshot(3, false), false)
	if _, err := provider.Source().Fetch(bg); err != nil {
		t.Fatal(err)
	}
	use("user-2")
	provider.FlushEvents()
	if n := len(relay.posts()); n != 1 {
		t.Fatalf("%d posts after the experiment stopped", n)
	}
}

func TestShutdownSendsWhatIsLeft(t *testing.T) {
	relay, _, c := eventsProvider(t, experimentSnapshot(1, true), Options{})
	user := of.NewEvaluationContext("user-1", nil)
	c.StringValue(bg, "checkout-button", "x", user)
	c.Track(bg, "purchase", user, of.NewTrackingEventDetails(3))
	of.Shutdown()
	if x, e := relay.sent(t); len(x) != 1 || len(e) != 1 {
		t.Fatalf("sent %v %v", x, e)
	}
}

func TestEventsCanBeTurnedOff(t *testing.T) {
	relay, provider, c := eventsProvider(t, experimentSnapshot(1, true), Options{DisableEvents: true})
	user := of.NewEvaluationContext("user-1", nil)
	if v, _ := c.StringValue(bg, "checkout-button", "x", user); v == "x" {
		t.Fatal("flag not evaluated")
	}
	c.Track(bg, "purchase", user, of.NewTrackingEventDetails(3))
	provider.FlushEvents()
	provider.Shutdown()
	if n := len(relay.posts()); n != 0 {
		t.Fatalf("%d posts with events disabled", n)
	}
}

// An evaluation that returns the caller's default isn't an exposure, even when the flag itself was a SPLIT.
func TestDefaultsAreNotExposures(t *testing.T) {
	snap := experimentSnapshot(1, true)
	snap["experiments"].(map[string]any)["flags"] = []any{"checkout-button", "limit"}
	snap["flags"].(map[string]any)["limit"].(map[string]any)["fallthrough"] = map[string]any{"rollout": map[string]any{"weights": []any{0, 0, 100_000}}}
	relay, provider, c := eventsProvider(t, snap, Options{})
	user := of.NewEvaluationContext("user-1", nil)
	if d, _ := c.IntValueDetails(bg, "limit", 7, user); d.ErrorCode != of.TypeMismatchCode { // 2.5 isn't an integer
		t.Fatalf("limit as int: %+v", d)
	}
	if d, _ := c.BooleanValueDetails(bg, "checkout-button", false, user); d.ErrorCode != of.TypeMismatchCode {
		t.Fatalf("checkout-button as bool: %+v", d)
	}
	if d, _ := c.ObjectValueDetails(bg, "checkout-button", nil, user); d.ErrorCode != of.TypeMismatchCode {
		t.Fatalf("checkout-button as object: %+v", d)
	}
	provider.FlushEvents()
	if n := len(relay.posts()); n != 0 {
		t.Fatalf("%d posts for defaults", n)
	}
	if v, _ := c.FloatValue(bg, "limit", 7, user); v != 2.5 {
		t.Fatalf("limit = %v", v)
	}
	variant, _ := c.StringValue(bg, "checkout-button", "x", user)
	provider.FlushEvents()
	exposures, _ := relay.sent(t)
	want := []any{
		map[string]any{"flag": "limit", "variation": 2.0, "key": "user-1"},
		map[string]any{"flag": "checkout-button", "variation": map[string]float64{"control": 0, "blue": 1}[variant], "key": "user-1"},
	}
	if !reflect.DeepEqual(exposures, want) {
		t.Fatalf("exposures %v", exposures)
	}
}

func TestSendsAtMost1000OfEachPerRequest(t *testing.T) {
	relay := newFakeRelay(t)
	s := testSender(t, relay.URL, nil)
	for i := 0; i < 2500; i++ {
		s.exposure(exposureRecord{Flag: "f", Variation: i % 2, Key: fmt.Sprintf("user-%d", i)})
	}
	for i := 0; i < 1200; i++ {
		s.event(trackRecord{Event: "purchase", Key: "user-1", Value: float64(i)})
	}
	s.flush()
	posts := relay.posts()
	var sizes []string
	for _, p := range posts {
		x, _ := p.body["exposures"].([]any)
		e, _ := p.body["events"].([]any)
		if x == nil || e == nil {
			t.Fatalf("null instead of []: %v", p.body)
		}
		sizes = append(sizes, fmt.Sprintf("%d/%d", len(x), len(e)))
	}
	if got := strings.Join(sizes, " "); got != "1000/1000 1000/200 500/0" {
		t.Fatalf("batches %s", got)
	}
	exposures, events := relay.sent(t)
	if exposures[0].(map[string]any)["key"] != "user-0" || exposures[2499].(map[string]any)["key"] != "user-2499" || events[1199].(map[string]any)["value"] != 1199.0 {
		t.Fatal("order not kept")
	}
}

func TestQueuesAreCappedWithOneWarning(t *testing.T) {
	relay := newFakeRelay(t)
	logs := &logBuffer{}
	s := testSender(t, relay.URL, logs)
	for i := 0; i < maxEventQueue+50; i++ {
		s.event(trackRecord{Event: "purchase", Key: "u", Value: 1})
	}
	s.flush()
	if _, events := relay.sent(t); len(events) != maxEventQueue {
		t.Fatalf("sent %d events", len(events))
	}
	if n := logs.count("queue full"); n != 1 {
		t.Fatalf("warned %d times", n)
	}
}

func TestFailedSendsAreDroppedAndLoggedOnceAMinute(t *testing.T) {
	relay := newFakeRelay(t)
	logs := &logBuffer{}
	s := testSender(t, relay.URL, logs)
	for _, status := range []int{http.StatusTooManyRequests, http.StatusInternalServerError, http.StatusNotFound} {
		relay.mu.Lock()
		relay.eventStatus = status
		relay.mu.Unlock()
		s.exposure(exposureRecord{Flag: "f", Variation: 0, Key: fmt.Sprint(status)})
		s.event(trackRecord{Event: "purchase", Key: "u", Value: 1})
		s.flush()
	}
	relay.mu.Lock()
	relay.eventStatus = 0
	relay.mu.Unlock()
	s.flush() // the failed batches were dropped: nothing left
	if n := len(relay.posts()); n != 3 {
		t.Fatalf("%d posts", n)
	}
	if n := logs.count("not accepted"); n != 1 {
		t.Fatalf("logged %d times: %s", n, logs.b.String())
	}

	// The relay can't be reached at all.
	dead := httptest.NewServer(http.NotFoundHandler())
	dead.Close()
	logs = &logBuffer{}
	s = testSender(t, dead.URL, logs)
	for i := 0; i < 3; i++ {
		s.event(trackRecord{Event: "purchase", Key: "u", Value: 1})
		s.flush()
	}
	if n := logs.count("not sent"); n != 1 {
		t.Fatalf("logged %d times: %s", n, logs.b.String())
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if len(s.events) != 0 {
		t.Fatalf("%d events kept", len(s.events))
	}
}

func TestSendsEarlyWhen500AreQueued(t *testing.T) {
	relay, _, c := eventsProvider(t, experimentSnapshot(1, true), Options{EventsInterval: time.Hour})
	track := func(i int) {
		c.Track(bg, "purchase", of.NewEvaluationContext(fmt.Sprintf("user-%d", i), nil), of.NewTrackingEventDetails(1))
	}
	for i := 0; i < eventSendAt-1; i++ {
		track(i)
	}
	time.Sleep(50 * time.Millisecond)
	if n := len(relay.posts()); n != 0 {
		t.Fatalf("%d posts before %d were queued", n, eventSendAt)
	}
	track(eventSendAt)
	waitFor(t, "an early send", func() bool { _, e := relay.sent(t); return len(e) == eventSendAt })
}

func TestExposureDedupe(t *testing.T) {
	d := newExposureDedupe(3)
	a0, a1, b, c := exposureRecord{"f", 0, "a"}, exposureRecord{"f", 1, "a"}, exposureRecord{"f", 0, "b"}, exposureRecord{"f", 0, "c"}
	for i, step := range []struct {
		r    exposureRecord
		want bool
	}{
		{a0, true}, {a0, false},
		{a1, true}, // a new variation for the same user is sent again
		{b, true}, {a0, false},
		{c, true},  // full: forgets a0, the oldest
		{a0, true}, // forgets a1
		{b, false}, {a1, true},
	} {
		if got := d.first(step.r); got != step.want {
			t.Fatalf("step %d: first(%v) = %v", i, step.r, got)
		}
	}
	if len(d.seen) != 3 || len(d.order) != 3 {
		t.Fatalf("%d seen, %d in order", len(d.seen), len(d.order))
	}
}

func TestEventsFromManyGoroutines(t *testing.T) {
	relay, provider, c := eventsProvider(t, experimentSnapshot(1, true), Options{EventsInterval: 5 * time.Millisecond})
	var wg sync.WaitGroup
	for g := 0; g < 8; g++ {
		wg.Go(func() {
			for i := 0; i < 300; i++ {
				user := of.NewEvaluationContext(fmt.Sprintf("user-%d", i), nil)
				c.StringValue(bg, "checkout-button", "x", user)
				c.Track(bg, "purchase", user, of.NewTrackingEventDetails(1))
			}
		})
	}
	wg.Wait()
	provider.Shutdown()
	exposures, events := relay.sent(t)
	if len(exposures) != 300 || len(events) != 8*300 {
		t.Fatalf("sent %d exposures and %d events", len(exposures), len(events))
	}
}
